    protected void replaceParentInfo(PSSystem pSSystem, CloneSession cloneSession) throws Exception {
        IEntity iEntity;
        super.replaceParentInfo((IEntity)pSSystem, cloneSession);
        if (pSSystem.getPSDevCenterTSId() != null && (iEntity = cloneSession.getEntity("PSDEVCENTERTS", (Object)pSSystem.getPSDevCenterTSId())) != null) {
            this.onFillParentInfo_PSDevCenterTS(pSSystem, (PSDevCenterTS)iEntity);
        }
        if (pSSystem.getPSDevCenterId() != null && (iEntity = cloneSession.getEntity("PSDEVCENTER", (Object)pSSystem.getPSDevCenterId())) != null) {
            this.onFillParentInfo_PSDevCenter(pSSystem, (PSDevCenter)iEntity);
        }
        if (pSSystem.getPSDevSlnId() != null && (iEntity = cloneSession.getEntity("PSDEVSLN", (Object)pSSystem.getPSDevSlnId())) != null) {
            this.onFillParentInfo_PSDevSln(pSSystem, (PSDevSln)iEntity);
        }
        if (pSSystem.getCLEmptyTextPSLanResId() != null && (iEntity = cloneSession.getEntity("PSLANGUAGERES", (Object)pSSystem.getCLEmptyTextPSLanResId())) != null) {
            this.onFillParentInfo_CLEmptyTextPSLanRes(pSSystem, (PSLanguageRes)iEntity);
        }
        if (pSSystem.getPSLanguageId() != null && (iEntity = cloneSession.getEntity("PSLANGUAGE", (Object)pSSystem.getPSLanguageId())) != null) {
            this.onFillParentInfo_PSLanguage(pSSystem, (PSLanguage)iEntity);
        }
        if (pSSystem.getPSSFId() != null && (iEntity = cloneSession.getEntity("PSSF", (Object)pSSystem.getPSSFId())) != null) {
            this.onFillParentInfo_PSSF(pSSystem, (PSSF)iEntity);
        }
        if (pSSystem.getPSSysEngineCfgId() != null && (iEntity = cloneSession.getEntity("PSSYSENGINECFG", (Object)pSSystem.getPSSysEngineCfgId())) != null) {
            this.onFillParentInfo_PSSysEngineCfg(pSSystem, (PSSysEngineCfg)iEntity);
        }
        if (pSSystem.getSrcPSSystemId() != null && (iEntity = cloneSession.getEntity("PSSYSTEM", (Object)pSSystem.getSrcPSSystemId())) != null) {
            this.onFillParentInfo_SrcPSSystem(pSSystem, (PSSystem)iEntity);
        }
    }

